async function submitCheckout(form){if(!cart.length){toast('Sua sacola está vazia.');go('/loja');return}const d=new FormData(form),button=form.querySelector('[type="submit"]');button.disabled=true;button.textContent='Enviando pedido…';const payload={requestId:d.get('request_id'),website:d.get('website'),acceptPrivacy:d.get('accept_privacy')==='on',customer:{name:d.get('name'),phone:d.get('phone'),email:d.get('email'),cpf:d.get('cpf'),postalCode:d.get('postal_code'),address:d.get('address'),addressExtra:d.get('address_extra'),cityState:d.get('city_state')},items:cart.map(x=>({id:x.id,size:x.size||'',color:x.color||'',quantity:x.qty}))};try{const result=await window.DEJBackend.submitOrder(payload);put('last-order-id',result.orderId);cart=[];put('cart',cart);go('/obrigado')}catch(error){toast(error.message||'Não foi possível enviar o pedido. Confira seus dados e tente novamente.');button.disabled=false;button.textContent='Enviar pedido'}}function observe(){let io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(x=>io.observe(x))}const renderHistoryRoute=()=>{window.__dejNextRouteTransition=true;render()};window.addEventListener('popstate',renderHistoryRoute);window.addEventListener('hashchange',renderHistoryRoute);document.documentElement.dataset.theme=(()=>{try{return localStorage.getItem('dej-theme')||'dark'}catch{return 'dark'}})();(async function bootCatalog(){try{if(window.DEJBackend?.configured){authUser=await window.DEJBackend.restoreOAuthCallback()||await window.DEJBackend.restoreSession();loadAccountCollections();try{const homeRows=await window.DEJBackend.loadHomeSections();if(Array.isArray(homeRows))window.DEJHomeSections?.set(homeRows)}catch(homeError){console.warn("Usando as configurações padrão da página inicial até a tabela home_sections existir.",homeError)}try{const remoteStamps=await window.DEJBackend.loadStamps();if(Array.isArray(remoteStamps)&&remoteStamps.length)stampCatalog=remoteStamps}catch(stampError){console.warn('Usando estampas locais até a tabela ser criada.',stampError)}const live=await Promise.race([window.DEJBackend.loadProducts(),new Promise(resolve=>setTimeout(()=>resolve(null),4000))]);if(Array.isArray(live)&&live.length)products=live}}catch(error){console.warn('Catálogo online indisponível; usando catálogo local.',error)}render()})();







